import unittest
import sys
sys.path.insert(0, ".")
from components.rubric_mappings.work import compute


class TestRubricMappings(unittest.TestCase):
    def test_public_example(self):
        payload = {"rubrics": {"a": ["X", "Y"], "b": ["Y", "X"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 3)
        self.assertEqual(mmap, {"a": {"X": 1, "Y": 2}, "b": {"X": 2, "Y": 1}})

    def test_single_bijection(self):
        payload = {"rubrics": {"a": ["X"], "b": ["Y"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 1)
        self.assertEqual(mmap, {"a": {"X": 1, "Y": 0}, "b": {"X": 0, "Y": 1}})

    def test_no_feasible(self):
        payload = {"rubrics": {"a": ["X"], "b": ["X"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 0)
        self.assertEqual(mmap, {"a": {"X": 0}, "b": {"X": 0}})


if __name__ == "__main__":
    unittest.main()
