import unittest
import sys
sys.path.insert(0, ".")
from components.rubric_mappings.work import compute


class TestRubricMappings(unittest.TestCase):
    def test_public_example(self):
        payload = {"rubrics": {"a": ["X", "Y"], "b": ["Y", "X"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 3)
        self.assertEqual(mmap, {"a": {"X": 1, "Y": 2}, "b": {"X": 2, "Y": 1}})

    def test_single_bijection(self):
        payload = {"rubrics": {"a": ["X"], "b": ["Y"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 1)
        self.assertEqual(mmap, {"a": {"X": 1, "Y": 0}, "b": {"X": 0, "Y": 1}})

    def test_three_labels_partial(self):
        # a: X,Y,Z ; b: X,Y,Z ; c: X,Y,Z -> all 6 permutations feasible
        payload = {"rubrics": {"a": ["X", "Y", "Z"], "b": ["X", "Y", "Z"], "c": ["X", "Y", "Z"]}}
        total, mmap = compute(payload)
        self.assertEqual(total, 63)  # 6 bits set
        # each (old,new) pair appears in exactly 2 of 6 permutations
        for o in ("a", "b", "c"):
            for n in ("X", "Y", "Z"):
                self.assertEqual(bin(mmap[o][n]).count("1"), 2)


if __name__ == "__main__":
    unittest.main()
