from fractions import Fraction
from itertools import combinations


def _gcd(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a


def _simplify(num, den):
    if den < 0:
        num, den = -num, -den
    g = _gcd(num, den)
    return [num // g, den // g]


def combine(payload, left, right):
    # left: [total_mask, old_label -> {new_label: mask}]
    # right: {course_code: [stats, reach]}
    total_mask = left[0]
    old_to_new_mask = left[1]
    courses = right

    # Identify comparable prefixes: both -2013J and -2014J present.
    prefixes = set()
    for code in courses:
        if code.endswith("-2013J") or code.endswith("-2014J"):
            prefixes.add(code.rsplit("-", 1)[0])

    comparable = []
    for p in sorted(prefixes):
        old_code = p + "-2013J"
        new_code = p + "-2014J"
        if old_code in courses and new_code in courses:
            comparable.append(p)

    # Build per-prefix item info.
    # For each prefix: old items (id, label, nonnull count, score sum), new items.
    prefix_info = {}
    for p in comparable:
        old_stats, old_reach = courses[p + "-2013J"]
        new_stats, new_reach = courses[p + "-2014J"]

        old_items = []
        for row in old_stats:
            iid, label, frac, cnt = row
            old_items.append((iid, label, cnt, frac[0], frac[1]))
        new_items = []
        for row in new_stats:
            iid, label, frac, cnt = row
            new_items.append((iid, label, cnt, frac[0], frac[1]))

        prefix_info[p] = {
            "old_items": old_items,
            "new_items": new_items,
            "old_reach": old_reach,
            "new_reach": new_reach,
        }

    # Candidate pairs: (prefix, old_id, new_id) where both have >=1 scored.
    candidates = []
    for p in comparable:
        info = prefix_info[p]
        for (oid, olab, ocnt, osum, oden) in info["old_items"]:
            if ocnt == 0:
                continue
            for (nid, nlab, ncnt, nsum, nden) in info["new_items"]:
                if ncnt == 0:
                    continue
                candidates.append((p, oid, nid))

    # For each candidate, the set of feasible dictionaries (bitmask) that allow
    # old_label -> new_label. This is old_to_new_mask[olab][nlab].
    # We need to find, for each candidate, its allowed mask.
    cand_mask = {}
    for p in comparable:
        info = prefix_info[p]
        old_lab = {iid: lab for (iid, lab, cnt, s, d) in info["old_items"]}
        new_lab = {iid: lab for (iid, lab, cnt, s, d) in info["new_items"]}
        for (oid, olab, ocnt, osum, oden) in info["old_items"]:
            if ocnt == 0:
                continue
            for (nid, nlab, ncnt, nsum, nden) in info["new_items"]:
                if ncnt == 0:
                    continue
                cand_mask[(p, oid, nid)] = old_to_new_mask[olab][nlab]

    # Order consistency: for two pairs in same prefix, old order relation must
    # equal new order relation. Build reachability as sets.
    # reach maps id -> sorted list of reachable ids (transitive).
    def reach_set(reach, iid):
        return set(reach.get(iid, []))

    # Enumerate all alignments. An alignment is a set of candidate pairs such that:
    # - each old id used at most once, each new id used at most once (per prefix)
    # - all pairs' masks have nonempty intersection (a common feasible dictionary)
    # - order consistency within prefix.
    #
    # We maximize pairs, then support.

    # Group candidates by prefix.
    by_prefix = {}
    for c in candidates:
        by_prefix.setdefault(c[0], []).append(c)

    # For each prefix, enumerate valid subsets (matching + order consistency),
    # and compute the intersection mask of the subset.
    # Then combine across prefixes: intersection of all masks must be nonempty.

    prefix_subsets = {}
    for p in comparable:
        info = prefix_info[p]
        old_reach = info["old_reach"]
        new_reach = info["new_reach"]
        cands = by_prefix.get(p, [])
        n = len(cands)
        valid = []
        # Enumerate subsets via bitmask over candidates.
        for sub in range(1 << n):
            chosen = [cands[i] for i in range(n) if (sub >> i) & 1]
            if not chosen:
                continue
            # check old/new id uniqueness
            old_ids = set()
            new_ids = set()
            ok = True
            for (pp, oid, nid) in chosen:
                if oid in old_ids or nid in new_ids:
                    ok = False
                    break
                old_ids.add(oid)
                new_ids.add(nid)
            if not ok:
                continue
            # order consistency
            ok = True
            for (a, b) in combinations(chosen, 2):
                (_, oa, na) = a
                (_, ob, nb) = b
                old_rel = (oa in reach_set(old_reach, ob)) or (ob in reach_set(old_reach, oa))
                new_rel = (na in reach_set(new_reach, nb)) or (nb in reach_set(new_reach, na))
                if old_rel != new_rel:
                    ok = False
                    break
            if not ok:
                continue
            # intersection mask
            mask = None
            for c in chosen:
                m = cand_mask[c]
                mask = m if mask is None else (mask & m)
            if mask == 0:
                continue
            valid.append((chosen, mask))
        prefix_subsets[p] = valid

    # Combine across prefixes. Each prefix contributes a subset (possibly empty).
    # We need to find global alignment maximizing pairs then support.
    # Enumerate combinations of prefix subsets.
    best_pairs = -1
    best_support = -1
    best_alignments = []  # list of (frozenset of pairs, mask)

    # Recursive enumeration over prefixes.
    prefix_list = comparable

    def rec(idx, chosen_pairs, mask, pairs_count, support):
        nonlocal best_pairs, best_support, best_alignments
        if idx == len(prefix_list):
            if pairs_count > best_pairs:
                best_pairs = pairs_count
                best_support = support
                best_alignments = [(frozenset(chosen_pairs), mask)]
            elif pairs_count == best_pairs:
                if support > best_support:
                    best_support = support
                    best_alignments = [(frozenset(chosen_pairs), mask)]
                elif support == best_support:
                    best_alignments.append((frozenset(chosen_pairs), mask))
            return
        p = prefix_list[idx]
        # option: empty subset for this prefix
        rec(idx + 1, chosen_pairs, mask, pairs_count, support)
        for (chosen, m) in prefix_subsets[p]:
            new_mask = mask & m
            if new_mask == 0:
                continue
            new_pairs = pairs_count + len(chosen)
            new_support = support
            for c in chosen:
                (pp, oid, nid) = c
                info = prefix_info[pp]
                # find counts
                ocnt = None
                ncnt = None
                for (iid, lab, cnt, s, d) in info["old_items"]:
                    if iid == oid:
                        ocnt = cnt
                        break
                for (iid, lab, cnt, s, d) in info["new_items"]:
                    if iid == nid:
                        ncnt = cnt
                        break
                new_support += min(ocnt, ncnt)
            rec(idx + 1, chosen_pairs + list(chosen), new_mask, new_pairs, new_support)

    rec(0, [], total_mask, 0, 0)

    # If no alignment found (shouldn't happen since empty alignment always valid),
    # handle empty.
    if best_pairs == -1:
        best_pairs = 0
        best_support = 0
        best_alignments = [(frozenset(), total_mask)]

    pairs = best_pairs
    support = best_support
    ways = len(best_alignments)

    # forced: pairs present in all best alignments.
    if best_alignments:
        forced_set = set(best_alignments[0][0])
        for (s, m) in best_alignments[1:]:
            forced_set &= s
        forced = sorted(forced_set)
    else:
        forced = []

    # drift: min and max of (new mean - old mean) over best alignments.
    if pairs == 0:
        drift = None
    else:
        drifts = []
        for (s, m) in best_alignments:
            old_sum = 0
            old_cnt = 0
            new_sum = 0
            new_cnt = 0
            for (pp, oid, nid) in s:
                info = prefix_info[pp]
                for (iid, lab, cnt, ssum, dden) in info["old_items"]:
                    if iid == oid:
                        old_sum += ssum
                        old_cnt += cnt
                        break
                for (iid, lab, cnt, ssum, dden) in info["new_items"]:
                    if iid == nid:
                        new_sum += ssum
                        new_cnt += cnt
                        break
            old_mean = Fraction(old_sum, old_cnt)
            new_mean = Fraction(new_sum, new_cnt)
            drifts.append(new_mean - old_mean)
        drift_min = min(drifts)
        drift_max = max(drifts)
        drift = [_simplify(drift_min.numerator, drift_min.denominator),
                 _simplify(drift_max.numerator, drift_max.denominator)]

    return {
        "pairs": pairs,
        "support": support,
        "ways": ways,
        "forced": forced,
        "drift": drift,
    }

